@props([
    'invalid' => false,
    'size' => null,
    'autosize' => false,
    'counter' => false,
])

@aware([
    'fieldInvalid' => false,
])

@php
    use App\Support\Stencil\Form\FormControlClassMap;
    use App\Support\Stencil\Interaction\InteractionStateAttributes;

    $isInvalid = $invalid || $fieldInvalid;

    $formControl = app(FormControlClassMap::class);
    $interactionState = app(InteractionStateAttributes::class);

    $userClass = $attributes->get('class');
    $applyFullWidth = ! filled($userClass);

    $controlClasses = collect([
        'textarea__control',
        'block min-w-0',
        $formControl->textareaSurfaceClasses($size),
        'placeholder:text-zinc-500 dark:placeholder:text-zinc-400',
        $formControl->invalidFieldClasses(),
        $isInvalid ? 'border-red-500 focus-visible:ring-red-500/20 dark:border-red-500' : null,
        $autosize ? 'resize-none overflow-hidden' : null,
    ])->filter()->implode(' ');

    $wrapperClasses = collect([
        'textarea',
        $applyFullWidth ? 'w-full' : null,
        $userClass,
    ])->filter()->implode(' ');

    $wrapperAttributes = $attributes
        ->except(['class', 'class:textarea', 'textarea:class', 'autosize', 'counter'])
        ->class($wrapperClasses)
        ->merge([
            'data-textarea' => true,
        ]);

    if ($autosize) {
        $wrapperAttributes = $wrapperAttributes->merge(['data-textarea-autosize' => true]);
    }

    if ($counter) {
        $wrapperAttributes = $wrapperAttributes->merge(['data-textarea-counter' => true]);
    }

    $controlExtraClass = $attributes->get('class:textarea') ?? $attributes->get('textarea:class');

    $controlAttributes = $interactionState->apply(
        $attributes
            ->except(['class', 'class:textarea', 'textarea:class', 'autosize', 'counter'])
            ->class([$controlClasses, $controlExtraClass])
            ->merge([
                'data-textarea-control' => true,
            ]),
    );

    if ($isInvalid) {
        $controlAttributes = $controlAttributes->merge(['aria-invalid' => 'true']);
    }
@endphp

<div {{ $wrapperAttributes }}>
    <textarea {{ $controlAttributes }}>{{ $slot }}</textarea>
</div>

@if ($counter)
    <div
        class="textarea__counter mt-1 text-right text-xs text-zinc-500 dark:text-zinc-400"
        data-textarea-counter-display
    ></div>
@endif

/**
 * Stencil — autosize textarea and character counter (vanilla JS).
 */

const TEXTAREA_SELECTOR = '[data-textarea]';
const initialized = new WeakSet();

/**
 * @param {ParentNode} root
 */
export function initTextareas(root = document) {
    root.querySelectorAll(TEXTAREA_SELECTOR).forEach((element) => {
        if (!(element instanceof HTMLElement)) {
            return;
        }

        if (initialized.has(element)) {
            return;
        }

        initialized.add(element);
        bindTextarea(element);
    });
}

/**
 * @param {HTMLElement} root
 */
function bindTextarea(root) {
    /** @type {HTMLTextAreaElement | null} */
    const control = root.querySelector('[data-textarea-control]');

    if (!(control instanceof HTMLTextAreaElement)) {
        return;
    }

    const autosize = root.hasAttribute('data-textarea-autosize');
    const counter = root.hasAttribute('data-textarea-counter');
    const counterEl = root.querySelector('[data-textarea-counter-display]');

    if (autosize) {
        const resize = () => {
            control.style.height = 'auto';
            control.style.height = `${control.scrollHeight}px`;
        };

        control.addEventListener('input', resize);
        resize();
    }

    if (counter && counterEl instanceof HTMLElement) {
        const maxLength = control.maxLength > 0 ? control.maxLength : null;

        const update = () => {
            const length = control.value.length;
            counterEl.textContent = maxLength !== null
                ? `${length}/${maxLength}`
                : String(length);
        };

        control.addEventListener('input', update);
        update();
    }
}

document.addEventListener('stencil:mount', (event) => {
    if (!(event instanceof CustomEvent)) {
        return;
    }

    const mountRoot = event.detail?.root;

    if (!(mountRoot instanceof HTMLElement)) {
        return;
    }

    initTextareas(mountRoot);
});

if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => initTextareas());
    } else {
        initTextareas();
    }
}
